The signal here is exact expected output, so I'm using a deterministic Python evaluator instead of an LLM judge that "eyeballs" it. With only 3 cases and no request for unseen inputs, this runs in multi-task mode with no valset.

```json
{
  "seed_candidate": {
    "table_py": "def to_md(rows):
    out = []
    for r in rows:
        out.append('| ' + ' | '.join(r) + ' |')
    return '\n'.join(out)
"
  },
  "evaluator": {
    "type": "python",
    "timeout": 20,
    "code": "def evaluate(candidate, example):
    text = candidate if isinstance(candidate, str) else next(iter(candidate.values()), "")
    if example is None:
        example = {"input": [["a", "b"], ["c", "d"]], "expected": "| a | b |\n|---|---|\n| c | d |"}
    rows = example["input"]
    expected = example["expected"]
    try:
        ns = {}
        exec(compile(text, "<candidate>", "exec"), ns)
        got = ns["to_md"]([list(r) for r in rows])
    except Exception as e:
        return 0.0, {"input": rows, "expected": expected, "error": repr(e)}
    if not isinstance(got, str):
        return 0.0, {"input": rows, "expected": expected, "error": "to_md returned non-str: " + type(got).__name__}
    if got == expected:
        return 1.0, {"input": rows, "expected": expected, "got": got, "failing_checks": []}
    gl = got.split("\n")
    el = expected.split("\n")
    n = max(len(gl), len(el))
    matched = sum(1 for a, b in zip(gl, el) if a == b)
    line_diffs = []
    for i in range(n):
        g = gl[i] if i < len(gl) else None
        e = el[i] if i < len(el) else None
        if g != e:
            line_diffs.append({"line": i, "expected": e, "got": g})
    checks = []
    if len(gl) != len(el):
        checks.append("line_count: expected %d got %d" % (len(el), len(gl)))
    checks.append("line_mismatches")
    score = 0.9 * matched / n
    return score, {"input": rows, "expected": expected, "got": got, "lines_matched": "%d/%d" % (matched, n), "line_diffs": line_diffs, "failing_checks": checks}
