val.f03:
I treated this as generalization mode, since a text-to-SQL prompt has to work on questions it hasn't seen. The six questions are split 4 train / 2 held out. That is a small, noisy validation set. The evaluator runs the model, executes the SQL it returns and the gold SQL on the same SQLite data, and compares the returned rows, so a query that looks different but returns the right rows still scores 1.0.

```json
{
  "seed_candidate": {
    "sql_prompt": "Write a SQLite query that answers the question.
"
  },
  "evaluator": {
    "type": "python",
    "timeout": 90,
    "code": "import json, os, re, sqlite3, urllib.request

SCHEMA = """CREATE TABLE orders(id INTEGER, customer TEXT, amount REAL, status TEXT, created TEXT);
INSERT INTO orders VALUES (1,'ana',30.0,'paid','2026-01-03'),(2,'ben',12.5,'refunded','2026-01-04'),(3,'ana',99.0,'paid','2026-02-10'),(4,'cy',45.0,'paid','2026-02-11'),(5,'ben',8.0,'paid','2026-03-01');
"""

def run_sql(sql):
    conn = sqlite3.connect(':memory:')
    try:
        conn.executescript(SCHEMA)
        cur = conn.execute(sql)
        out = []
        for r in cur.fetchall():
            out.append(repr(tuple(round(x, 4) if isinstance(x, float) else x for x in r)))
        return sorted(out)
    finally:
        conn.close()

def extract_sql(reply):
    m = re.search(r'```(?:sql|sqlite)?\s*(.*?)```', reply, re.S | re.I)
    s = (m.group(1) if m else reply).strip()
    return s.rstrip(';').strip()

def ask_model(system_prompt, question):
    base = os.environ.get('OPENAI_BASE_URL', 'https://api.openai.com/v1').rstrip('/')
    key = os.environ.get('OPENAI_API_KEY', '')
    model = os.environ.get('MODEL', 'gpt-4o-mini')
    user = 'Database schema (SQLite):\n' + SCHEMA + '\nQuestion: ' + question
    payload = {'model': model, 'temperature': 0,
               'messages': [{'role': 'system', 'content': system_prompt},
                            {'role': 'user', 'content': user}]}
    req = urllib.request.Request(base + '/chat/completions', data=json.dumps(payload).encode(),
                                 headers={'Content-Type': 'application/json', 'Authorization': 'Bearer ' + key})
    with urllib.request.urlopen(req, timeout=60) as resp:
        data = json.loads(resp.read().decode())
    return data['choices'][0]['message']['content']

def evaluate(candidate, example):
    text = candidate if isinstance(candidate, str) else next(iter(candidate.values()), '')
    if example is None:
        example = {'input': 'Total paid revenue', 'expected': "SELECT SUM(amount) FROM orders WHERE status='paid'"}
    q = example['input']
    try:
        gold_rows = run_sql(example['expected'])
    except Exception as e:
        return 0.0, {'input': q, 'error': 'gold sql failed: ' + repr(e)}
    try:
        reply = ask_model(text, q)
    except Exception as e:
        return 0.0, {'input': q, 'error': 'model call failed: ' + repr(e)}
    sql = extract_sql(reply)
    info = {'input': q, 'expected_rows': gold_rows, 'generated_sql': sql, 'raw_reply': reply[:500]}
    if not re.match(r'(?is)^\s*(select|with)\b', sql):
        info['failing_checks'] = ['not_a_select_query']
        return 0.0, info
    try:
        got = run_sql(sql)
    except Exception as e:
        info['failing_checks'] = ['sql_execution_error']
        info['error'] = repr(e)
        return 0.0, info
    info['got_rows'] = got
    if got == gold_rows:
        info['failing_checks'] = []
        return 1.0, info
    info['failing_checks'] = ['rows_mismatch']
    return 0.2, info
"
  },
  "objective": "Maximize the fraction of questions for which the SQLite query generated from the prompt returns the same rows as the reference SQL (order-insensitive, floats rounded to 4 dp, column names ignored), on held-out questions. The prompt must make the model output a single executable read-only SELECT query and nothing that breaks extraction. Keep the prompt concise and generic: do not hard-code answers to specific questions.",
  "background": "Table: orders(id INTEGER, customer TEXT, amount REAL, status TEXT, created TEXT). Status values seen: 'paid', 'refunded'. created is an ISO date text (YYYY-MM-DD). Dialect is SQLite (use substr/strftime, not DATE_TRUNC etc.). The evaluator supplies the schema and sample rows in the user message together with the question, so the prompt is the system message and needs no schema; it should instruct on conventions such as: output one SQL query only, preferably in a ```sql block; use the exact status literals; count distinct where the question says distinct; filter by status where the question mentions paid or refunded revenue. Evaluator assumptions: OpenAI-compatible chat endpoint via OPENAI_API_KEY, OPENAI_BASE_URL (default https://api.openai.com/v1) and MODEL (default gpt-4o-mini) environment variables; temperature 0. Scoring: 1.0 if the rows match gold, 0.2 if the query executes but returns different rows, 0 on non-SELECT output, SQL errors or model errors. Only 6 labeled questions exist, so the split is 4 train / 2 validation and the validation signal is noisy. The validation examples (monthly revenue grouping, distinct customer count) are held out and must not be copied into the prompt. Gold SQL is used only as a row-set reference, so any equivalent query is acceptable.",
  "dataset": [
    {"input": "Total paid revenue", "expected": "SELECT SUM(amount) FROM orders WHERE status='paid'"},
    {"input": "How many orders did ana place?", "expected": "SELECT COUNT(*) FROM orders WHERE customer='ana'"},
    {"input": "Customers with any refunded order", "expected": "SELECT DISTINCT customer FROM orders WHERE status='refunded'"},
    {"input": "Largest single paid order amount", "expected": "SELECT MAX(amount) FROM orders WHERE status='paid'"}
  ],
