    {"input": "Revenue per month from paid orders", "expected": "SELECT substr(created,1,7), SUM(amount) FROM orders WHERE status='paid' GROUP BY 1"},
    {"input": "Number of distinct customers", "expected": "SELECT COUNT(DISTINCT customer) FROM orders"}
  ],
  "config": {"max_metric_calls": 48, "max_iterations": 8}
}
